#!/usr/bin/env bash
set -euo pipefail
image="$(realpath "$1")"
configuration="$2"
runtime="$(mktemp -d)"
(cd "$runtime" && "$image" --appimage-extract >/dev/null)
mapfile -t debs < <(find src-tauri/target/release/bundle/deb -maxdepth 1 -name '*.deb' -type f)
test "${#debs[@]}" -eq 1
dpkg-deb --extract "${debs[0]}" "$runtime/debian"
cp "$runtime/debian/usr/bin/active-classroom" "$runtime/squashfs-root/usr/bin/active-classroom"
chmod 755 src-tauri/packaging/debian-launcher.sh
# Use official DebConfig.files and the Debian executable already generated by
# Tauri, retaining its Debian bundle-type marker instead of AppImage's marker.
node --input-type=module - "$configuration" "$runtime/squashfs-root" <<'JS'
import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
const [configuration, runtime] = process.argv.slice(2);
const overlay = JSON.parse(await readFile(configuration, "utf8"));
overlay.bundle.linux = { deb: { files: {
  "/usr/bin/active-classroom": resolve("src-tauri/packaging/debian-launcher.sh"),
  "/usr/lib/active-classroom": runtime,
} } };
await writeFile(configuration, JSON.stringify(overlay));
JS
